import {COURSE,crew,createCase,simulatePayment,checks,investigate,rehearse,approve,applyRepair,verify,canOpenLesson,findings,changeSampleEvidence,restoreSampleEvidence} from './core.mjs';
import {reviewCard} from './review-ui.mjs';
const cfg=window.COURSELATCH_RUNTIME||{backend:false},root=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=simulatePayment(createCase()),view='merchant',busy=false,error='',lesson=false,consultOpen=false,source='',operator=false;
try{const saved=JSON.parse(sessionStorage.getItem('courselatch-v2'));if(saved?.schema===1&&saved.order&&saved.entitlement&&Array.isArray(saved.events))state=saved}catch{}
const portrait=i=>`<span class="portrait p${i}" aria-hidden="true"></span>`;
document.querySelector('#crew').innerHTML=crew.map((a,i)=>`<article class="crew-card">${portrait(i)}<h3>${a.name}</h3><div class="trait">${a.trait}</div><blockquote>“${a.hello}”</blockquote><p>${a.scope}</p></article>`).join('');
function persist(){if(!cfg.backend)try{sessionStorage.setItem('courselatch-v2',JSON.stringify(state))}catch{}}
async function api(path,data){const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const j=await r.json();if(!r.ok)throw Error(j.error||'The request could not complete.');return j}
function say(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(say.timer);say.timer=setTimeout(()=>t.classList.remove('show'),4500)}
function status(){if(state.phase==='paid'&&state.evidenceAvailable===false)return 'Payment evidence unavailable';if(state.phase==='paid'&&canOpenLesson(state))return 'Access present · review needed';return {reviewing:'Challenge round incomplete',unpaid:'Ready for checkout',paid:'Paid · access missing',investigated:'Evidence checked',blocked:'Stopped · conflicting evidence','needs-evidence':'Waiting for evidence','verify-only':'Already restored · verify only',stale:'Evidence changed · review expired',rehearsed:'Rehearsal passed · still locked',approved:'Approved · not yet applied',verifying:'Access updated · checking outcome',unverified:'Access updated · verification incomplete',verified:'Access verified'}[state.phase]||'Review needed'}
function button(action,text,style='green'){return `<button class="button ${style}" data-action="${action}" ${busy?'disabled':''}>${busy?'Working…':text}</button>`}
function actionPanel(){let title,desc,action,label;
 switch(state.phase){
 case 'unpaid':title='Start with the purchase.';desc='Visit the sample storefront and complete checkout. The demo deliberately fails the access update after payment.';action='learner';label='Open sample storefront';break;
 case 'reviewing':title='The challenge round is incomplete.';desc='Wait for the active workflow, or retry the investigation if the review was interrupted. No repair can proceed.';action='investigate';label='Retry investigation';break;
 case 'paid':title='Let’s check before we change.';desc='Match the payment to this purchase, check current access, and let Prism challenge the proposed next step.';action='investigate';label='Investigate this purchase';break;
 case 'blocked':title='The records don’t agree.';desc='An exact payment check failed. Inspect the open objection and request the correct evidence before considering any access grant.';action='request';label='Copy evidence request';break;
 case 'needs-evidence':title='Keep the repair on hold.';desc='The challenge round has an unanswered objection. Inspect its cited records, supply the missing evidence, then investigate again.';action=state.scenario==='missing'&&state.evidenceAvailable===false?'restore-evidence':'investigate';label=action==='restore-evidence'?'Demo: supply missing record':'Run a new investigation';break;
 case 'verify-only':title='No repair is needed.';desc='The store retry already restored this exact entitlement. Check the payment and lesson access without another grant.';action='verify';label='Verify existing access';break;
 case 'stale':title='Let’s review the new facts.';desc='The payment reference changed after review. The earlier recommendation and approval no longer apply.';action='investigate';label='Review changed evidence';break;
 case 'investigated':title='Preview one access grant.';desc='Rehearse the correction on a copy: this learner, this course, this existing payment. The original stays untouched.';action='rehearse';label='Rehearse the repair';break;
 case 'rehearsed':title='Your call. One exact change.';desc='The preview passed. Approve one access grant for Maya’s purchased course. Payment and price remain unchanged.';action='approve';label='Approve this access grant';break;
 case 'approved':title='Approval recorded.';desc='Revalidate the approved evidence, apply the grant once, then check the payment and protected lesson.';action='repair';label='Apply & verify access';break;
 case 'verifying':case 'unverified':title='Keep checking the outcome.';desc='The case stays open until all outcome checks pass. Retry the reads without granting access again.';action='verify';label='Retry verification only';break;
 case 'verified':title='Maya can start learning.';desc='The payment still matches. The access record is correct. The lesson-access check passed. Now open the learner’s view.';action='learner';label='See Maya’s restored access';break;
 }
 return `<aside class="panel action-panel"><div class="eyebrow">${state.phase==='blocked'?'PRISM / REPAIR ON HOLD':'MERCHANT DECISION'}</div><h3>${title}</h3><p>${desc}</p>${button(action,label)}<p class="fine">${state.phase==='blocked'?'No access granted. No financial action taken.':'No new charge. No refund. Only the purchased access.'}</p>${state.phase==='verified'?'<button class="quiet" data-action="receipt">Download recovery receipt ↓</button>':''}</aside>`}
function merchant(){const phases=['paid','investigated','rehearsed','approved','verifying','verified'];let n=phases.indexOf(state.phase);if(state.phase==='blocked')n=1;if(state.phase==='unverified')n=4;return `<div class="case-heading"><div><div class="eyebrow">RECOVERY CASE / ${esc(state.id)}</div><h3>${state.phase==='verified'?'Maya’s course is ready.':canOpenLesson(state)?'Access is present. Is the case resolved?':'Maya paid. Her course stayed locked.'}</h3><p>${COURSE.name} · $128.00 USD · Learner: Maya Chen</p></div><span class="status ${state.phase==='verified'?'good':state.phase==='blocked'?'stop':''}" role="status">${status()}</span></div><div class="progress" aria-label="Recovery progress">${['Investigate','Rehearse','Approve','Repair','Verify'].map((x,i)=>`<span class="${n>i?'done':n===i?'active':''}">${n>i?'✓':('0'+(i+1))} ${x}</span>`).join('')}</div><div class="decision-grid">${reviewCard(state,{open:consultOpen,source,busy})}${actionPanel()}</div><div class="desk-grid evidence-grid"><div><div class="panel"><h4>${state.proof?'Outcome checks':'What the records tell us'}</h4>${state.proof?`<div class="summary-box ${state.proof.passed?'':'stop'}"><strong>${state.proof.passed?'Verified access—not just a successful write.':'One or more checks are still unresolved.'}</strong>${state.proof.passed?'The existing payment, the purchased entitlement, and a lesson-access check agree.':'The correction is not repeated. Read the records again to verify the outcome.'}</div>${state.proof.checks.map(x=>checkRow(x)).join('')}<p class="fine">Checked ${new Date(state.proof.at).toLocaleTimeString()} · ${cfg.backend?'Server-side checks':'Browser simulation'}</p>`:`<div class="summary-box ${state.phase==='blocked'?'stop':''}"><strong>${state.phase==='blocked'?'Different order. Repair stopped.':state.evidenceAvailable===false?'Payment record unavailable.':canOpenLesson(state)?'Existing access found. Check the outcome.':state.capture?'Payment recorded. Access grant missing.':'Checkout hasn’t happened yet.'}</strong>${state.phase==='blocked'?'Ask for the correct payment reference before considering a grant.':state.evidenceAvailable===false?'The original payment evidence cannot be read. Eligibility remains undecided.':canOpenLesson(state)?'A store retry has already granted this access. The challenge round must prevent a duplicate correction.':state.capture?'The access-update job timed out. We know the failed step; the underlying cause is still unknown.':'Use the learner’s storefront to begin the sample purchase.'}</div><div class="checks">${(state.evidenceAvailable===false?[{label:'Payment record unavailable',ok:false,detail:'Request a fresh record before checking the match.'}]:checks(state)).map(checkRow).join('')}</div>`}${state.rehearsal?`<div class="diff"><div class="diff-head"><span>BEFORE / ORIGINAL</span><span>AFTER / REHEARSAL COPY</span></div><div class="diff-row"><span><strong>Locked</strong><br>No course entitlement</span><span><strong>Access granted</strong><br>Maya · Light & Story</span></div><div class="diff-row"><span>Existing $128 payment</span><span>Same capture · no charge</span></div></div><p class="preview-note">✓ Preview passed ${state.writes?'· approved change applied':'· original access is still locked'}</p>`:''}<div class="audit-meta"><span>Access writes: ${state.writes} · Verification attempts: ${state.reads}</span><span>${state.capture?.source==='paypal-sandbox'?'PayPal sandbox':'Sample records'}</span></div></div></div></div><details class="audit"><summary>Recovery timeline & audit trail</summary><ul>${state.events.map(e=>`<li><time>${new Date(e.at).toLocaleTimeString()}</time>${esc(e.what)}</li>`).join('')}</ul></details>`}
function checkRow(c){return `<div class="check ${c.ok?'':'fail'}"><b aria-label="${c.ok?'Passed':'Not passed'}">${c.ok?'✓':'!'}</b><div><strong>${esc(c.label)}</strong>${c.detail?`<small>${esc(c.detail)}</small>`:''}</div></div>`}
const cover=()=>`<div class="course-cover"><div class="sun"></div><div class="arch"></div><div class="arch arch-two"></div><span>STILLFRAME / WORKSHOPS</span><strong>The Light<br>& Story<br>Workshop.</strong><small>Sample course · 3 short exercises</small></div>`;
function learner(){if(lesson)return `<div class="lesson"><div class="eyebrow">ACCESS CHECK PASSED / ${COURSE.lesson}</div><h4>Find the light before the frame.</h4><p>You’re inside the sample lesson. This is the customer outcome the recovery was meant to restore.</p><ol><li>Find a window with soft, indirect daylight.</li><li>Place an everyday object beside it.</li><li>Make three frames: facing the light, beside it, and against it.</li></ol><div class="exercise"><strong>Your first exercise</strong><p>Notice how the same object tells a different story as the light moves. Which frame feels most like a beginning?</p></div>${button('back','Back to my course','dark')}</div>`;return `<div class="learner-grid"><div class="learner-art">${cover()}</div><div class="learner-info"><div class="eyebrow">MAYA’S SAMPLE STOREFRONT</div><h3>A different way<br>of seeing.</h3><p>A hands-on introduction to light, composition, and visual storytelling. Your purchase should unlock the first lesson immediately.</p><div class="price">$128 <small>USD · one-time purchase</small></div>${state.capture?`<div class="lock-message"><strong>${canOpenLesson(state)?'Your course access is restored.':'Payment received. Your course is still locked.'}</strong><br>${canOpenLesson(state)?'Open the lesson to see the recovery from the learner’s side.':'Please don’t pay again. The merchant needs to check your purchase.'}</div>${button(canOpenLesson(state)?'lesson':'merchant',canOpenLesson(state)?'Open my first lesson ↗':'Visit the recovery desk','dark')}`:`${button('pay','Complete sample checkout · $128','dark')}<p class="fine">Simulated checkout. No PayPal login or real payment.</p>${cfg.paypal&&operator?'<div id="paypal-buttons" style="margin-top:20px"></div><p class="fine">Optional PayPal sandbox checkout · test accounts only.</p>':''}`}<p class="fine" style="margin-top:17px">${cfg.backend?'Sample learner account in this server session.':'Browser-only demonstration. This page is not a protected course platform.'}</p></div></div>`}
function render(){root.setAttribute('aria-busy',String(busy));root.innerHTML=`<div class="workbench"><div class="workbar"><div><span class="mode-tag">${cfg.backend?'SERVER DEMO':'BROWSER DEMO'}</span><label>Try a case <select aria-label="Sample case" ${busy?'disabled':''}>${[['match','A · Correct payment, missing access'],['conflict','B · Wrong order reference'],['read-error','C · Verification read fails once'],['missing','D · Missing payment evidence'],['restored','E · Access already restored'],['changed','F · Evidence changes after review']].map(([v,t])=>`<option value="${v}" ${state.scenario===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="view-tabs" role="tablist" aria-label="View the story"><button role="tab" aria-selected="${view==='merchant'}" data-view="merchant">Merchant desk</button><button role="tab" aria-selected="${view==='learner'}" data-view="learner">Learner storefront</button></div></div><div class="workbody">${error?`<div class="error-banner" role="alert">${esc(error)}</div>`:''}${view==='merchant'?merchant():learner()}</div><div class="demo-controls"><p>${cfg.backend?'Server session · durable sample records · integrations run only after operator unlock':'Sample records and scripted agents run in this tab. Reset to replay the purchase.'}</p><button class="reset" data-action="reset" ${busy?'disabled':''}>Restart story ↺</button></div></div>${cfg.backend&&!operator?'<details class="operator"><summary>Developer setup: unlock configured integrations</summary><form id="operator-form"><label>Demo operator key<input type="password" name="key" autocomplete="off" required></label><button class="button outline small">Unlock this session</button></form></details>':''}`;
 root.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;lesson=false;render()});root.querySelector('select').onchange=e=>run('scenario',{scenario:e.target.value});root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>run(b.dataset.action));root.querySelector('.consult')?.addEventListener('toggle',e=>{if(e.target.isConnected)consultOpen=e.target.open});root.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{source=source===b.dataset.source?'':b.dataset.source;consultOpen=true;render()});root.querySelector('#operator-form')?.addEventListener('submit',async e=>{e.preventDefault();try{await api('operator',{key:new FormData(e.target).get('key')});operator=true;render();say('Configured integrations unlocked for this session.')}catch(e){error=e.message;render()}});if(!busy&&view==='learner'&&!state.capture&&cfg.paypal&&operator)mountPayPal();}
async function run(action,data={}){if(busy)return;error='';if(['merchant','learner','back'].includes(action)){view=action==='merchant'?'merchant':'learner';lesson=false;return render()}if(action==='receipt'){const blob=new Blob([JSON.stringify({brand:'CourseLatch',mode:cfg.backend?'server-demo':'browser-simulation',case:state.id,approval:state.approval,review:state.review,proof:state.proof,writes:state.writes,events:state.events},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='courselatch-recovery-'+state.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return}if(action==='request'){const message='Please share the receipt and order reference for your Light & Story purchase. We are holding the access repair while we resolve: '+(state.review?.objections.filter(o=>o.status==='open').map(o=>o.resolution).join(' ')||'a payment evidence mismatch.');try{await navigator.clipboard.writeText(message);say('Evidence request copied. Nothing was sent.')}catch{error=message;render()}return}busy=true;render();try{
 if(action==='lesson'){if(cfg.backend)await api('lesson');else if(!canOpenLesson(state))throw Error('This course is still locked.');lesson=true;view='learner';}
 else if(cfg.backend){let result=await api('action',{action,...data,planId:state.rehearsal?.id});state=result.state;if(result.job){say('Workflow started. Refreshing its result…');for(let i=0;i<60;i++){await new Promise(r=>setTimeout(r,1000));const update=await api('state');state=update.state;if(!state.job?.pending)break;}if(state.job?.pending)say('Workflow is still running. You can refresh the page later.');if(state.job?.error)throw Error(state.job.error)}}
 else if(action==='pay')simulatePayment(state);
 else if(action==='investigate')investigate(state);
 else if(action==='change-evidence')changeSampleEvidence(state);
 else if(action==='restore-evidence')restoreSampleEvidence(state);
 else if(action==='rehearse')rehearse(state);
 else if(action==='approve')approve(state,state.rehearsal?.id);
 else if(action==='repair'){applyRepair(state);verify(state,{paymentAvailable:state.scenario!=='read-error'});}
 else if(action==='verify')verify(state);
 else if(action==='reset')state=createCase(state.scenario);
 else if(action==='scenario')state=simulatePayment(createCase(data.scenario));
 if(action==='reset'){view='learner';lesson=false;}if(action==='scenario'){view='merchant';lesson=false;source='';consultOpen=false;}if(action==='pay')say('Sample payment received. Access update deliberately failed.');persist();
 }catch(e){error=e.message;if(cfg.backend)try{const current=await api('state');state=current.state}catch{}}finally{busy=false;render()}}
let paypalLoading,paypalFailed=false;
async function mountPayPal(){if(paypalFailed)return;try{if(!paypalLoading)paypalLoading=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://www.paypal.com/sdk/js?client-id='+encodeURIComponent(cfg.paypalClientId)+'&currency=USD&intent=capture';script.onload=resolve;script.onerror=()=>reject(Error('PayPal sandbox checkout could not load.'));document.head.append(script)});await paypalLoading;if(!document.querySelector('#paypal-buttons')||document.querySelector('#paypal-buttons').children.length)return;window.paypal.Buttons({createOrder:async()=>{const r=await api('paypal/create',{});return r.id},onApprove:async data=>{try{const r=await api('paypal/capture',{orderId:data.orderID});state=r.state;render();say('Sandbox payment captured. Access failure injected for the demo.')}catch(e){error=e.message;render()}},onError:()=>{paypalFailed=true;error='Sandbox checkout could not complete. Check the server configuration and try again.';render()}}).render('#paypal-buttons')}catch(e){paypalFailed=true;error=e.message;render()}}
if(cfg.backend){try{const r=await api('state');state=r.state;operator=r.operator}catch(e){error=e.message}}render();

